// Block (composition) — avatar preview with image selection and removal actions.
// Avatar, FileTrigger, and Button own behavior/look; Stack owns arrangement.
import type { Ref } from "react";
import { Avatar } from "../components/Avatar";
import { Button } from "../components/Button";
import { FileTrigger } from "../components/FileTrigger";
import { Stack } from "../layouts/Stack";
import "./AvatarUploader.css";

export interface AvatarUploaderProps {
  src?: string;
  name?: string;
  onSelect?: (file: File) => void;
  onRemove?: () => void;
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

export function AvatarUploader({
  src,
  name,
  onSelect,
  onRemove,
  className,
  ref,
}: AvatarUploaderProps) {
  const fallback = name
    ?.split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase())
    .join("");

  return (
    <Stack
      ref={ref}
      direction="row"
      align="center"
      gap="small"
      className={className ? `sd-avataruploader ${className}` : "sd-avataruploader"}
    >
      <Avatar size="large" src={src} alt={name ?? "Profile avatar"}>
        {fallback}
      </Avatar>
      <Stack gap="x-small" className="sd-avataruploader__actions">
        <FileTrigger
          acceptedFileTypes={["image/*"]}
          onSelect={(files) => {
            const file = files?.item(0);
            if (file) onSelect?.(file);
          }}
        >
          <Button type="button">Upload</Button>
        </FileTrigger>
        {src && (
          <Button type="button" variant="secondary" onPress={onRemove}>
            Remove
          </Button>
        )}
      </Stack>
    </Stack>
  );
}

/* AvatarUploader.css — arrangement is fully expressed by Stack. */
.sd-avataruploader {
  width: 100%;
}
